public class Solution extends VersionControl {
    public int firstBadVersion(int n) {
        int good = 0;
        int bad = n;
        while (good + 1 < bad) {
            int mid = good + (bad - good) / 2;
            if (isBadVersion(mid)) {
                bad = mid;
            } else {
                good = mid;
            }
        }
        return bad;
    }
}

