public class Solution extends VersionControl {
    public int firstBadVersion(int n) {
        return search(1, n, true);
    }

    private int search(int left, int right, boolean active) {
        if (left == right) {
            return left;
        }
        int mid = left + (right - left) / 2;
        if (isBadVersion(mid)) {
            return search(left, mid, active);
        }
        return search(mid + 1, right, active);
    }
}
